const businessDate=()=>{const parts=new Intl.DateTimeFormat("en-US",{timeZone:businessTimezone,year:"numeric",month:"2-digit",day:"2-digit"}).formatToParts(new Date()),part=type=>parts.find(value=>value.type===type)?.value||"";return `${part("year")}-${part("month")}-${part("day")}`};
