/* --- Certification issuer mark upload -------------------------------------
   The logo is an issuer brand asset, so it is uploaded and stored separately
   from the certificate document. Cloudinary keeps the binary; MongoDB only
   stores the secure URL and public id. */
app.post("/api/admin/certifications/:id/logo",admin,imageUpload("logo"),asyncRoute(async(req,res)=>{
  const record=await Certification.findById(req.params.id);
  if(!record)return res.status(404).json({error:"Certification not found."});
  if(!req.file)return res.status(400).json({error:"Choose an image file to upload.",code:"LOGO_REQUIRED"});
  if(!storageConfigured())return res.status(503).json({error:"Cloudinary storage is not configured.",code:"STORAGE_NOT_CONFIGURED"});
  await validateImageBuffer(req.file.buffer,{allowedTypes:["image/png","image/jpeg","image/webp"],maxBytes:4*1024*1024,label:"Certification logo"});
  const uploaded=await cloudUpload(Readable.from(req.file.buffer),{resource_type:"image",folder:"solarious/certifications",public_id:`cert-logo-${String(record._id)}-${Date.now()}`,format:"png"});
  await Certification.findByIdAndUpdate(record._id,{logoUrl:uploaded.secure_url,logoStorageId:uploaded.public_id});
  const previous=record.logoStorageId;
  if(previous&&previous!==uploaded.public_id)await destroyUpload(previous).catch(error=>console.error("[certification:cloudinary:cleanup]",{message:String(error?.message||"Unknown error").slice(0,300)}));
  await ProtectedAudit.create({action:"certifications.logo",actor:adminUsername,details:{id:String(record._id),name:record.name}}).catch(()=>{});
  res.json({ok:true,logoUrl:uploaded.secure_url});
}));
app.delete("/api/admin/certifications/:id/logo",admin,asyncRoute(async(req,res)=>{
  const record=await Certification.findById(req.params.id);
  if(!record)return res.status(404).json({error:"Certification not found."});
  if(record.logoStorageId)await destroyUpload(record.logoStorageId).catch(error=>console.error("[certification:cloudinary:cleanup]",{message:String(error?.message||"Unknown error").slice(0,300)}));
  await Certification.findByIdAndUpdate(record._id,{logoUrl:"",logoStorageId:""});
  await ProtectedAudit.create({action:"certifications.logo.remove",actor:adminUsername,details:{id:String(record._id)}}).catch(()=>{});
  res.json({ok:true});
}));

